import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Project 3: Build a Simple Website (Advanced Level)","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-5/project-3.md","filePath":"en/modules/module-5/project-3.md"}'),n={name:"en/modules/module-5/project-3.md"};function o(l,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="project-3-build-a-simple-website-advanced-level" tabindex="-1">Project 3: Build a Simple Website (Advanced Level) <a class="header-anchor" href="#project-3-build-a-simple-website-advanced-level" aria-label="Permalink to &quot;Project 3: Build a Simple Website (Advanced Level)&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Learn to use natural language to have Codex generate and modify webpages ⏱️ <strong>Estimated Time</strong>: 40 minutes 🎯 <strong>Skills learned</strong>: Natural language programming, iterative optimization, testing &amp; validation</p></blockquote><hr><h2 id="i-task-description" tabindex="-1">I. Task Description <a class="header-anchor" href="#i-task-description" aria-label="Permalink to &quot;I. Task Description&quot;">​</a></h2><p>Use natural language to have Codex generate a personal profile webpage.</p><hr><h2 id="ii-operation-steps" tabindex="-1">II. Operation Steps <a class="header-anchor" href="#ii-operation-steps" aria-label="Permalink to &quot;II. Operation Steps&quot;">​</a></h2><h3 id="step-1-describe-your-requirements" tabindex="-1">Step 1: Describe Your Requirements <a class="header-anchor" href="#step-1-describe-your-requirements" aria-label="Permalink to &quot;Step 1: Describe Your Requirements&quot;">​</a></h3><p>Open Codex and type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me build a personal profile webpage with these requirements:</span></span>
<span class="line"><span>- Include an avatar area (use a placeholder)</span></span>
<span class="line"><span>- Display name and a one-sentence bio</span></span>
<span class="line"><span>- Skills list (displayed as tags, 3-5 skills)</span></span>
<span class="line"><span>- Contact info area (email and social media links)</span></span>
<span class="line"><span>- Clean, modern overall style with blue as the primary color</span></span>
<span class="line"><span>- Save the code as index.html</span></span></code></pre></div><h3 id="step-2-review-the-generated-result" tabindex="-1">Step 2: Review the Generated Result <a class="header-anchor" href="#step-2-review-the-generated-result" aria-label="Permalink to &quot;Step 2: Review the Generated Result&quot;">​</a></h3><p>Codex will generate complete HTML code. Save the code as <code>index.html</code>, double-click to open it in a browser, and check the result.</p><h3 id="step-3-request-modifications-based-on-what-you-see" tabindex="-1">Step 3: Request Modifications Based on What You See <a class="header-anchor" href="#step-3-request-modifications-based-on-what-you-see" aria-label="Permalink to &quot;Step 3: Request Modifications Based on What You See&quot;">​</a></h3><p>After observing the page, you might have these thoughts:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. &quot;Change the avatar from a circle to a rounded square&quot;</span></span>
<span class="line"><span>2. &quot;Add a project showcase section below the skills list&quot;</span></span>
<span class="line"><span>3. &quot;Change the color scheme to dark mode&quot;</span></span>
<span class="line"><span>4. &quot;Add an &#39;About Me&#39; paragraph, about 200 words&quot;</span></span>
<span class="line"><span>5. &quot;Make the page look good on mobile too (responsive design)&quot;</span></span></code></pre></div><h3 id="step-4-iterative-optimization" tabindex="-1">Step 4: Iterative Optimization <a class="header-anchor" href="#step-4-iterative-optimization" aria-label="Permalink to &quot;Step 4: Iterative Optimization&quot;">​</a></h3><p>Each time you make a modification request, Codex will update the code. Repeat this process until you&#39;re satisfied.</p><hr><h2 id="iii-advanced-challenges" tabindex="-1">III. Advanced Challenges <a class="header-anchor" href="#iii-advanced-challenges" aria-label="Permalink to &quot;III. Advanced Challenges&quot;">​</a></h2><h3 id="add-interactive-features" tabindex="-1">Add Interactive Features <a class="header-anchor" href="#add-interactive-features" aria-label="Permalink to &quot;Add Interactive Features&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a button to the page that toggles between dark and light themes when clicked.</span></span></code></pre></div><h3 id="add-animation-effects" tabindex="-1">Add Animation Effects <a class="header-anchor" href="#add-animation-effects" aria-label="Permalink to &quot;Add Animation Effects&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add some simple animation effects to the page, such as fade-in elements, hover effects, etc.</span></span></code></pre></div><h3 id="deploy-online" tabindex="-1">Deploy Online <a class="header-anchor" href="#deploy-online" aria-label="Permalink to &quot;Deploy Online&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me generate a project structure that can be directly deployed to GitHub Pages.</span></span></code></pre></div><hr><h2 id="iv-in-lesson-practice-checklist" tabindex="-1">IV. In-Lesson Practice Checklist <a class="header-anchor" href="#iv-in-lesson-practice-checklist" aria-label="Permalink to &quot;IV. In-Lesson Practice Checklist&quot;">​</a></h2><p>Complete the following tasks in order:</p><ul><li>[ ] Have Codex generate the first version of a personal profile webpage</li><li>[ ] Preview the result in a browser</li><li>[ ] Go through at least 3 rounds of modification and optimization</li><li>[ ] Save the final version locally</li></ul><hr><h2 id="v-summary" tabindex="-1">V. Summary <a class="header-anchor" href="#v-summary" aria-label="Permalink to &quot;V. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill Learned</th><th>Description</th></tr></thead><tbody><tr><td>Natural language programming</td><td>Describe webpage requirements in natural language</td></tr><tr><td>Iterative optimization</td><td>Continuously refine through multiple rounds of follow-up</td></tr><tr><td>Testing &amp; validation</td><td>Check results in a browser</td></tr><tr><td>Problem solving</td><td>Tell Codex how to improve when you find issues</td></tr></tbody></table><hr><h2 id="vi-next-step" tabindex="-1">VI. Next Step <a class="header-anchor" href="#vi-next-step" aria-label="Permalink to &quot;VI. Next Step&quot;">​</a></h2><p><a href="./project-4.html">→ Project 4: Todo List App</a></p>`,35)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
